core.crypto]] ]=[[
-- SHA-256 for downloaded file integrity. Native 5.3 fallback is local code.
local b=bit32
if not b then
  local chunk=assert(load([=[return {
    band=function(a,b) return (a & b) & 0xffffffff end,
    bor=function(a,b) return (a | b) & 0xffffffff end,
    bxor=function(a,b,c) return ((a ~ b) ~ (c or 0)) & 0xffffffff end,
    bnot=function(a) return (~a) & 0xffffffff end,
    rshift=function(a,n) return (a & 0xffffffff) >> n end,
    rrotate=function(a,n) return (((a & 0xffffffff) >> n) | (a << (32-n))) & 0xffffffff end
  }]=],"=factoryos/local-bitops","t",{}),"Lua 5.2 bit32 or Lua 5.3 required")
  b=chunk()
end
local band, bxor, bnot, rshift, ror = b.band, b.bxor, b.bnot, b.rshift, b.rrotate
local M = {}
local K = {
  0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2}
local function word(n)
  return string.char(band(rshift(n,24),255), band(rshift(n,16),255), band(rshift(n,8),255), band(n,255))
end
function M.sha256(s, raw)
  local len = #s
  s = s .. "\128" .. string.rep("\0", (55-len)%64) .. word(math.floor(len/536870912)) .. word((len*8)%4294967296)
  local h = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}
  for offset=1,#s,64 do
    local w = {}
    for i=0,15 do
      local a,c,d,e = s:byte(offset+i*4,offset+i*4+3)
      w[i] = a*16777216+c*65536+d*256+e
    end
    for i=16,63 do
      local x,y = w[i-15],w[i-2]
      w[i] = (w[i-16]+bxor(ror(x,7),ror(x,18),rshift(x,3))+w[i-7]+bxor(ror(y,17),ror(y,19),rshift(y,10)))%4294967296
    end
    local a,c,d,e,f,g,j,k = table.unpack(h)
    for i=0,63 do
      local t1 = (k+bxor(ror(f,6),ror(f,11),ror(f,25))+bxor(band(f,g),band(bnot(f),j))+K[i+1]+w[i])%4294967296
      local t2 = (bxor(ror(a,2),ror(a,13),ror(a,22))+bxor(band(a,c),band(a,d),band(c,d)))%4294967296
      k,j,g,f,e,d,c,a = j,g,f,(e+t1)%4294967296,d,c,a,(t1+t2)%4294967296
    end
    local v = {a,c,d,e,f,g,j,k}
    for i=1,8 do h[i]=(h[i]+v[i])%4294967296 end
  end
  local out = {}
  for i=1,8 do out[i] = raw and word(h[i]) or string.format("%08x",h[i]) end
  return table.concat(out)
end
function M.equal(a,c)
  if type(a)~="string" or type(c)~="string" or #a~=#c then return false end
  local diff=0
  for i=1,#a do diff=b.bor(diff,bxor(a:byte(i),c:byte(i))) end
  return diff==0
end
return M
]]
sources[ [[
core.storage]] ]=[[
local fs = require("filesystem")
local codec = require("core.codec")
local M = {}
function M.mkdir(path)
  if fs.exists(path) then
    if fs.isDirectory(path) then return true end
    return nil,"Path is not a directory: "..path
  end
  return fs.makeDirectory(path)
end
function M.read(path, limit)
  local f, err=io.open(path,"rb"); if not f then return nil,err end
  local s=f:read((limit or 65536)+1); f:close()
  if not s then return "" end
  if #s>(limit or 65536) then return nil,"file too large: "..path end
  return s
end
function M.write(path,s)
  local made,why=M.mkdir(fs.path(path)); if not made then return nil,why end
  local f,err=io.open(path,"wb"); if not f then return nil,err end
  local ok,reason=f:write(s)
  -- OpenOS close returns no values; flush must be checked before closing.
  if ok and f.flush then ok,reason=f:flush() end
  local closed,closeErr=pcall(f.close,f)
  if not ok or not closed then return nil,reason or closeErr end
  return true
end
function M.atomic(path,s)
  local ok,err=M.write(path..".tmp",s); if not ok then return nil,err end
  if fs.exists(path) then
    if fs.exists(path..".bak") then assert(fs.remove(path..".bak")) end
    assert(fs.rename(path,path..".bak"))
  end
  ok,err=fs.rename(path..".tmp",path)
  if not ok and fs.exists(path..".bak") then fs.rename(path..".bak",path) end
  return ok,err
end
function M.load(path)
  local s,err=M.read(path); if not s then return nil,err end
  return codec.decode(s)
end
function M.save(path,value) return M.atomic(path,codec.encode(value)) end
return M
]]
sources[ [[
core.hardware]] ]=[[
local component=require("component")
local M={}
function M.select(kind,address,optional)
  if address and address~="" then
    local ok,p=pcall(component.proxy,address)
    if ok and p and p.type==kind then return p end
    return nil,"Configured "..kind.." missing: "..address
  end
  local list={}
  for addr in component.list(kind,true) do list[#list+1]=addr end
  if #list==1 then return component.proxy(list[1]) end
  if #list==0 then return nil,(optional and "Optional " or "Missing ")..kind end
  return nil,"Multiple "..kind.." components; select exact address with factoryos config "..kind.." ADDRESS"
end
function M.check(c)
  local modem,err=M.select("modem",c.modem)
  if not modem then return nil,err end
  if not modem.isWireless() then return nil,"Wireless Network Card required" end
  local gpu,ge=M.select("gpu",c.gpu)
  if not gpu then return nil,ge end
  local screen,se=M.select("screen",c.screen)
  if not screen then return nil,se end
  local ok,reason=gpu.bind(screen.address,false)
  if not ok then return nil,"GPU bind failed: "..tostring(reason) end
  local w,h=gpu.maxResolution()
  if w<40 or h<12 then return nil,"Screen/GPU requires at least 40x12 characters" end
  return {modem=modem,gpu=gpu,screen=screen,maxWidth=w,maxHeight=h,
    internet=component.isAvailable("internet")}
end
function M.describe()
  local lines={}
  for address,kind in component.list() do
    lines[#lines+1]=kind.." "..address
  end
  table.sort(lines)
  local ok,info=pcall(function() return require("computer").getDeviceInfo() end)
  if ok and type(info)=="table" then
    for address in component.list("modem",true) do
      local entry=info[address]
      if type(entry)=="table" then lines[#lines+1]="modem packet capacity "..address..": "..tostring(entry.capacity).." bytes" end
    end
  end
  return table.concat(lines,"\n")
end
return M
]]
sources[ [[
core.config]] ]=[[
local storage=require("core.storage")
local fs=require("filesystem")
local M={path="/etc/factoryos/config.dat"}
function M.defaults(role)
  return {schema=2,role=role or "server",port=34100,strength=64,serverAddress="",
    modem="",gpu="",screen="",allowedClients={},heartbeat=5,offlineAfter=18,poll=10,
    ae2Address="",ae2Enabled=true,updateBase=""}
end
function M.upgrade(c)
  if type(c)=="table" and (c.schema==1 or c.schema==2) then
    c.schema=2; c.key=nil
  end
  return c
end
function M.validate(c)
  if type(c)~="table" or c.schema~=2 then return nil,"invalid config schema" end
  if c.role~="server" and c.role~="main" and c.role~="side" then return nil,"invalid role" end
  for _,key in ipairs({"port","strength","heartbeat","offlineAfter","poll"}) do
    local n=c[key]; if type(n)~="number" or n~=n or n==math.huge then return nil,"invalid "..key end
  end
  if c.port%1~=0 or c.port<1 or c.port>65535 then return nil,"invalid port" end
  if c.strength<1 or c.strength>400 or c.heartbeat<2 or c.heartbeat>60 or c.offlineAfter<c.heartbeat*3 or c.offlineAfter>300 or c.poll<5 or c.poll>300 then return nil,"invalid intervals/strength" end
  for _,k in ipairs({"serverAddress","modem","gpu","screen","ae2Address","updateBase"}) do
    if type(c[k])~="string" or #c[k]>512 then return nil,"invalid "..k end
  end
  if type(c.ae2Enabled)~="boolean" then return nil,"invalid feature flags" end
  if type(c.allowedClients)~="table" then return nil,"invalid client allowlist" end
  local count=0
  for address,role in pairs(c.allowedClients) do
    count=count+1
    if type(address)~="string" or #address<8 or #address>64 or (role~="main" and role~="side") then return nil,"invalid client entry" end
  end
  if count>16 then return nil,"at most 16 clients" end
  return true
end
function M.load()
  local c,err=storage.load(M.path)
  c=M.upgrade(c)
  local valid,why=M.validate(c)
  if valid then return c end
  local backup=M.upgrade(storage.load(M.path..".bak"))
  if M.validate(backup) then return backup,"config invalid; using .bak (original preserved)" end
  return nil,"Config unavailable: "..tostring(err or why)..". Run factoryos config or restore config.dat.bak."
end
function M.save(c)
  c=M.upgrade(c)
  local ok,err=M.validate(c); if not ok then return nil,err end
  if fs.exists(M.path) and not M.validate(M.upgrade(storage.load(M.path))) and M.validate(M.upgrade(storage.load(M.path..".bak"))) then
    if fs.exists(M.path..".corrupt") then assert(fs.remove(M.path..".corrupt")) end
    assert(fs.rename(M.path,M.path..".corrupt"))
  end
  return storage.save(M.path,c)
end
return M
]]
sources[ [[
core.updater]] ]=[[
local fs=require("filesystem")
local component=require("component")
local computer=require("computer")
local uuid=require("uuid")
local codec=require("core.codec")
local crypto=require("core.crypto")
local storage=require("core.storage")
local M={root="/usr/lib/factoryos"}
M.launcher=[=[local root="/usr/lib/factoryos"
local f=io.open(root.."/active","r") or io.open(root.."/active.bak","r")
assert(f,"FactoryOS not installed")
local v=f:read("*l"); f:close()
assert(v and v:match("^[%w%._%-]+$") and not v:find("..",1,true),"Invalid active release")
return assert(loadfile(root.."/releases/"..v.."/boot.lua"))(root,{...})
]=]
function M.validate(manifest)
  assert(type(manifest)=="table" and manifest.schema==1,"Invalid manifest schema")
  local v=manifest.release
  assert(type(v)=="string" and #v<=80 and v:match("^[%w%._%-]+$") and not v:find("..",1,true),"Invalid release")
  assert(type(manifest.files)=="table" and #manifest.files>0 and #manifest.files<=128,"Invalid file count")
  local paths,total={},0
  for _,file in ipairs(manifest.files) do
    assert(type(file)=="table" and type(file.path)=="string" and #file.path<=160,"Invalid file entry")
    local path=file.path
    assert(path:match("^[%w_/%-]+%.lua$") and path:sub(1,1)~="/" and not path:find("..",1,true) and not path:find("//",1,true),"Unsafe manifest path")
    assert(not paths[path],"Duplicate manifest path"); paths[path]=true
    assert(type(file.size)=="number" and file.size>=1 and file.size%1==0 and file.size<=65536,"Invalid file size")
    assert(type(file.sha256)=="string" and #file.sha256==64 and file.sha256:match("^[a-f0-9]+$"),"Invalid file hash")
    total=total+file.size
  end
  assert(total<=524288,"Release exceeds memory/disk budget")
  for _,required in ipairs({"boot.lua","core/cli.lua","core/config.lua","core/runtime.lua","core/updater.lua"}) do assert(paths[required],"Incomplete release: "..required) end
  return total
end
function M.fetch(url,limit)
  assert(type(url)=="string" and url:match("^https://[%w%.%-]+/[^%s]*$"),"Use an HTTPS source URL")
  local internet,err=require("core.hardware").select("internet","")
  assert(internet,"Internet Card required for download: "..tostring(err))
  assert(internet.isHttpEnabled(),"HTTP disabled in OpenComputers config")
  local handle,requestError=internet.request(url)
  assert(handle,"HTTP request failed: "..tostring(requestError))
  local deadline=computer.uptime()+25
  local ok,result=xpcall(function()
    while not handle.finishConnect() do
      assert(computer.uptime()<deadline,"HTTP connect timeout"); os.sleep(0.05)
    end
    local code=handle.response()
    assert(code==200,"HTTP status "..tostring(code).." for "..url)
    local chunks,bytes={},0
    while true do
      assert(computer.uptime()<deadline,"HTTP download timeout")
      local data,why=handle.read(4096)
      if data==nil then assert(not why,why); break end
      if #data==0 then os.sleep(0.05)
      else
        bytes=bytes+#data; assert(bytes<=limit,"Download size limit")
        chunks[#chunks+1]=data
      end
    end
    return table.concat(chunks)
  end,debug.traceback)
  handle.close()
  assert(ok,result)
  return result
end
function M.source(base)
  assert(type(base)=="string" and base~="","No update source configured. Supply a real HTTPS repository base or --local PATH.")
  base=base:gsub("/+$","")
  if base:match("^https://") then
    return function(path,limit) return M.fetch(base.."/"..path,limit) end
  end
  error("Updates require HTTPS; offline installer accepts --local PATH")
end
function M.stage(get,root)
  root=root or M.root
  local manifest=assert(codec.decode(get("manifest.dat",65536)),"Cannot decode manifest")
  local bytes=M.validate(manifest)
  assert(storage.mkdir(root.."/releases"))
  local proxy=fs.get(root)
  if proxy and proxy.spaceTotal and proxy.spaceUsed then
    assert(proxy.spaceTotal()-proxy.spaceUsed()>bytes+65536,"Insufficient disk space (old release retained)")
  end
  local release=root.."/releases/"..manifest.release
  local stage=root.."/releases/.stage-"..uuid.next()
  assert(storage.mkdir(stage))
  for i,file in ipairs(manifest.files) do
    io.write(string.format("[%02d/%02d] %s\n",i,#manifest.files,file.path))
    local data=get("src/"..file.path,file.size)
    assert(#data==file.size and crypto.equal(crypto.sha256(data),file.sha256),"Integrity failure: "..file.path)
    assert(storage.write(stage.."/"..file.path,data))
    os.sleep(0)
  end
  assert(storage.write(stage.."/manifest.dat",codec.encode(manifest)))
  if fs.exists(release) then
    -- Immutable existing release must match every downloaded file before reusing it.
    for _,file in ipairs(manifest.files) do
      local data=assert(storage.read(release.."/"..file.path,file.size))
      assert(#data==file.size and crypto.sha256(data)==file.sha256,"Existing release differs; publish a new release ID")
    end
    assert(fs.remove(stage))
  else assert(fs.rename(stage,release)) end
  return manifest
end
function M.activate(manifest,root)
  root=root or M.root
  local old=storage.read(root.."/active",100) or storage.read(root.."/active.bak",100)
  if old and old~=manifest.release.."\n" then assert(storage.atomic(root.."/previous",old)) end
  assert(storage.atomic(root.."/active",manifest.release.."\n"))
end
function M.install(base,cfg,root)
  root=root or M.root
  assert(cfg.role=="server" or component.isAvailable("internet"),"Display needs temporary Internet Card or offline reinstall")
  local manifest=M.stage(M.source(base),root)
  M.activate(manifest,root)
  return manifest
end
function M.rollback(root)
  root=root or M.root
  local previous=assert(storage.read(root.."/previous",100),"No previous release")
  local v=previous:match("^([%w%._%-]+)\n?$")
  assert(v and not v:find("..",1,true),"Invalid rollback pointer")
  local manifest=assert(storage.load(root.."/releases/"..v.."/manifest.dat"))
  M.validate(manifest)
  assert(manifest.release==v,"Rollback manifest mismatch")
  for _,f in ipairs(manifest.files) do
    local data=assert(storage.read(root.."/releases/"..v.."/"..f.path,f.size))
    assert(#data==f.size and crypto.sha256(data)==f.sha256,"Rollback integrity failure")
  end
  M.activate(manifest,root)
end
return M
]]
sources[ [[
core.installer]] ]=[[
local fs=require("filesystem")
local component=require("component")
local hardware=require("core.hardware")
local config=require("core.config")
local storage=require("core.storage")
local updater=require("core.updater")
local M={}
local function ask(label,default)
  io.write(label..(default and (" ["..default.."]") or "")..": ")
  io.stdout:flush()
  -- OpenOS cursor echo can retain password/newline options between reads.
  -- Create a fresh unmasked cursor and own the newline for every prompt.
  local line=require("term").read({dobreak=false})
  io.write("\n")
  assert(line,"Installation cancelled")
  line=line:gsub("[\r\n]+$","")
  if line=="" then return default or "" end
  return line
end
local function selectHardware(kind,configured)
  local value,err=hardware.select(kind,configured)
  if value then return value.address end
  print(err)
  local addresses={}
  for address in component.list(kind,true) do addresses[#addresses+1]=address; print(#addresses..". "..address) end
  assert(#addresses>0,"Required component missing: "..kind)
  return assert(addresses[tonumber(ask("Select "..kind))],"Invalid component selection")
end
function M.main(args,embedded)
  local service=package.loaded["factoryos.service"]
  assert(not service or (not service.running and (not service.thread or service.thread:status()=="dead")),"Stop FactoryOS before installing")
  print("=================================\n       FACTORY OS INSTALLER\n=================================")
  print("1. Factory Server\n2. Main Display (8x5)\n3. Side Display (4x5)")
  local role=({["1"]="server",["2"]="main",["3"]="side"})[ask("Select installation")]
  assert(role,"Select 1, 2 or 3")
  local old=config.load()
  local c=old or config.defaults(role)
  c.role=role
  c.modem=selectHardware("modem",c.modem)
  c.gpu=selectHardware("gpu",c.gpu)
  c.screen=selectHardware("screen",c.screen)
  print("Local modem: "..c.modem)
  print("No password required. Displays pair by modem address.")
  if role=="server" then
    if not component.isAvailable("internet") then print("Warning: Internet Card absent. Offline installation works; online updates unavailable.") end
    local main=ask("Main display modem address (blank = configure later)","")
    local side=ask("Side display modem address (blank = configure later)","")
    if main~="" then c.allowedClients[main]="main" end
    if side~="" then c.allowedClients[side]="side" end
  else c.serverAddress=ask("Server modem address (blank = automatic discovery)",c.serverAddress) end
  assert(config.validate(c))
  local hw,err=hardware.check(c); assert(hw,err)
  print("GPU/screen: "..hw.maxWidth.."x"..hw.maxHeight.." characters")
  print("Hardware OK. Runtime registration test: start server and both displays after setup.")
  local get
  if embedded then
